const $=s=>document.querySelector(s);const routes={overview:'Overview',campaigns:'Campaigns',accounts:'Ad accounts',assets:'Creative library',network:'Network profiles',reports:'Reports'};
const icons=['<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>','<path d="M4 11v6h4l10 4V5L8 9H4v2Zm4 6 2 5M21 9v8"/>','<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M8 5V3h8v2M3 11h18M10 10v3h4v-3"/>','<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 3-3 5 5"/>','<path d="m12 2 8 4v7c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>','<path d="M5 3h10l4 4v14H5Z M9 16v-4m4 4V8m4 8v-6"/>'];
$('nav').innerHTML=Object.entries(routes).map(([key,name],i)=>`<a href="#${key}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">${icons[i]}</svg>${name}${key==='campaigns'?'<span class="nav-count">6</span>':''}</a>`).join('');
function head(title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">NORTHSTAR COLLECTIVE</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${action}</div></div>`}
function stats(){return `<div class="summary">${[['Total ad spend','₹1,84,600','Sample reporting period',''],['Attributed revenue','₹7,42,200','Platform-reported sample','₹'],['Conversions','1,286','Illustrative conversion events','◎'],['Blended ROAS','4.02×','Attributed revenue ÷ spend','']].map(([a,b,c,d])=>`<div class="metric"><span class="metric-symbol">${d}</span><div class="label">${a}</div><div class="value">${b}</div><div class="caption">${c}</div></div>`).join('')}</div>`}
function chart(){return `<div class="panel"><div class="panel-head"><div><h2>Performance over time</h2><p>Daily attributed revenue · 11–17 September 2026</p></div><div class="legend"><span><i></i>Revenue</span></div></div><div class="chart"><svg viewBox="0 0 650 230" role="img" aria-label="Sample daily revenue rises from 82 thousand rupees to 138 thousand rupees across seven days."><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#2462f1" stop-opacity=".16"/><stop offset="1" stop-color="#2462f1" stop-opacity="0"/></linearGradient></defs>${[40,85,130,175].map((y,i)=>`<path d="M40 ${y}H635" stroke="#edf0f6"/><text x="0" y="${y+4}" fill="#8a98ad" font-size="10">${140-i*30}k</text>`).join('')}<path d="M40 127L138 111L236 133L334 78L432 96L530 51L628 43V200H40Z" fill="url(#area)"/><path d="M40 127L138 111L236 133L334 78L432 96L530 51L628 43" fill="none" stroke="#2462f1" stroke-width="3" stroke-linejoin="round"/>${[[40,127],[138,111],[236,133],[334,78],[432,96],[530,51],[628,43]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#2462f1" stroke-width="2"/>`).join('')}</svg><div class="chart-labels">${['11 Sep','12 Sep','13 Sep','14 Sep','15 Sep','16 Sep','17 Sep'].map(d=>`<span>${d}</span>`).join('')}</div></div></div>`}
const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const money=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:0});
const symbols={Meta:'∞',Google:'G',LinkedIn:'in',TikTok:'♪',Microsoft:'▦',X:'𝕏',Pinterest:'P'};
const platform=p=>`<span class="platform ${p.toLowerCase()}">${symbols[p]}</span>`;
const initial=[{id:101,name:'The everyday collection',brand:'Northstar Studio',platform:'Meta',objective:'Sales',status:'Active',budget:3500,spend:48200,revenue:231360,conversions:426,asset:0},{id:102,name:'High-intent search',brand:'Northstar Studio',platform:'Google',objective:'Sales',status:'Active',budget:4200,spend:56400,revenue:259440,conversions:398,asset:1},{id:103,name:'Autumn arrivals',brand:'Form & Field',platform:'Meta',objective:'Traffic',status:'Active',budget:1800,spend:24600,revenue:86100,conversions:183,asset:2},{id:104,name:'B2B growth playbook',brand:'Orbit Software',platform:'LinkedIn',objective:'Leads',status:'Paused',budget:2500,spend:32400,revenue:81000,conversions:127,asset:1},{id:105,name:'Made for your everyday',brand:'Form & Field',platform:'TikTok',objective:'Awareness',status:'In review',budget:1500,spend:23000,revenue:84300,conversions:152,asset:0},{id:106,name:'September brand search',brand:'Orbit Software',platform:'Google',objective:'Traffic',status:'Draft',budget:1200,spend:0,revenue:0,conversions:0,asset:1}];
let campaigns=structuredClone(initial),currentRoute='overview',query='',filter='All',platformFilter='All',accountFilter='All',storageAvailable=true;
const profiles={'Meta / Northstar Studio':'Mumbai · Dedicated 01','Google / Northstar Studio':'Mumbai · Dedicated 02','Meta / Form & Field':'Singapore · Dedicated 03','LinkedIn / Orbit Software':'London · Dedicated 04','TikTok / Form & Field':'Singapore · Dedicated 03','Google / Orbit Software':'Mumbai · Dedicated 02'};
const assets=[{title:'Everyday essentials',brand:'Northstar Studio',tag:'NORTHSTAR STUDIO',headline:'Less noise.<br>More you.',line:'The everyday collection / September 2026',style:'',size:'1080 × 1080',type:'Social creative'},{title:'Your next chapter',brand:'Orbit Software',tag:'ORBIT / WORK BETTER',headline:'Great work.<br>Less busywork.',line:'Make room for what matters.',style:'sun',size:'1200 × 628',type:'Display creative'},{title:'Autumn, considered',brand:'Form & Field',tag:'FORM & FIELD',headline:'A little change.<br>A new season.',line:'Discover the autumn collection.',style:'lilac',size:'1080 × 1350',type:'Social creative'}];
try{let saved=JSON.parse(sessionStorage.getItem('srs-ad-demo')||'null');if(saved&&Array.isArray(saved.campaigns)&&saved.campaigns.length<=100&&saved.campaigns.every(c=>Number.isInteger(c.id)&&typeof c.name==='string'&&c.name.length<=100&&['Meta','Google','LinkedIn','TikTok'].includes(c.platform)&&['Active','Paused','Draft','In review'].includes(c.status)&&Number.isFinite(c.budget)&&c.budget>=100&&c.budget<=1000000&&[c.spend,c.revenue,c.conversions].every(n=>Number.isFinite(n)&&n>=0)&&typeof c.brand==='string'&&typeof c.objective==='string'&&Number.isInteger(c.asset)&&c.asset>=0&&c.asset<3&&Object.hasOwn(profiles,c.platform+' / '+c.brand))){campaigns=saved.campaigns;for(const [k,v]of Object.entries(saved.profiles||{}))if(Object.hasOwn(profiles,k)&&Object.values(profiles).includes(v))profiles[k]=v}}catch(e){storageAvailable=false}
function save(){try{sessionStorage.setItem('srs-ad-demo',JSON.stringify({campaigns,profiles}))}catch(e){storageAvailable=false;toast('Changes apply in memory only; browser storage is unavailable.')}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function badge(status){return `<span class="badge ${status==='In review'?'review':status.toLowerCase()}">${esc(status)}</span>`}
function rows(list,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Platform</th><th>Status</th><th>Daily budget</th><th>Spend</th><th>ROAS</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td class="campaign-name">${esc(c.name)}<small>${esc(c.brand)} · ${esc(c.objective)}</small></td><td><span style="display:flex;gap:8px;align-items:center">${platform(c.platform)}${c.platform}</span></td><td>${badge(c.status)}</td><td>${money(c.budget)}</td><td>${money(c.spend)}</td><td>${c.spend?(c.revenue/c.spend).toFixed(2)+'×':'—'}</td><td><button class="row-button" data-action="detail" data-id="${c.id}" aria-label="Review ${esc(c.name)}">Open</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty"><h3>No campaigns match</h3>Try another filter or search.<br><button data-action="clear" style="margin-top:15px">Clear filters</button></div></td></tr>'}</tbody></table></div>`}
function visibleCampaigns(){return campaigns.filter(c=>(filter==='All'||c.status===filter)&&(platformFilter==='All'||c.platform===platformFilter)&&`${c.name} ${c.brand} ${c.objective}`.toLowerCase().includes(query.toLowerCase()))}
function overview(){const review=campaigns.filter(c=>c.status==='In review').length;return head('Your advertising, in focus.','A clear view across every account. One workspace to take action.','<button data-action="export" data-type="performance">↓ Export report</button><button class="primary" data-action="create">Create campaign</button>')+`<div class="period-line"><span>11–17 September 2026</span><span>INR · Sample reporting period</span></div>`+stats()+`<div class="grid-two">${chart()}<div class="panel"><div class="panel-head"><div><h2>Spend by platform</h2><p>Across 6 sample ad accounts</p></div><span class="tiny-label">7 DAYS</span></div>${['Meta','Google','LinkedIn','TikTok'].map(p=>{let total=campaigns.filter(c=>c.platform===p).reduce((a,c)=>a+c.spend,0);return `<div class="split-row">${platform(p)}<div class="split-info"><strong>${p} Ads</strong><div class="progress-track"><span style="width:${total/184600*100}%"></span></div></div><div class="split-amount">${money(total)}<small>${(total/184600*100).toFixed(1)}% of spend</small></div></div>`}).join('')}</div></div>`+`<div class="attention"><span class="symbol">◷</span><div><strong>${review?`${review} campaign${review>1?'s':''} awaiting your review`:'You’re all caught up'}</strong><p>${review?'Check the creative and budget before simulated publishing.':'There are no campaigns awaiting workspace approval.'}</p></div><button data-action="reviews">${review?'Review campaigns':'View campaigns'} </button></div><div class="panel"><div class="panel-head"><div><h2>Campaign snapshot</h2><p>Recent campaigns across your workspace</p></div><button class="textbtn" data-action="go" data-route="campaigns">View campaigns</button></div>${rows(campaigns.slice(0,4),true)}<div class="panel-bottom"><span>${campaigns.filter(c=>c.status==='Active').length} active · ${campaigns.length} total campaigns</span><span>All performance figures are illustrative</span></div></div>`}
function campaignView(){return head('Campaigns','Create campaigns, review changes and manage delivery.','<button data-action="export" data-type="filtered">↓ Export</button><button class="primary" data-action="create">Create campaign</button>')+`<div class="filters"><div class="tabs" role="group" aria-label="Campaign status">${['All','Active','In review','Draft','Paused'].map(s=>`<button data-filter="${s}" class="${filter===s?'selected':''}" aria-pressed="${filter===s}">${s}</button>`).join('')}</div><select id="platform-filter" aria-label="Filter campaigns by platform">${['All','Meta','Google','LinkedIn','TikTok'].map(p=>`<option ${platformFilter===p?'selected':''} value="${p}">${p==='All'?'All platforms':p}</option>`).join('')}</select><input id="search" aria-label="Search campaigns" placeholder="Search campaigns or clients…" value="${esc(query)}"></div><div class="panel" id="campaign-results">${rows(visibleCampaigns())}<div class="panel-bottom"><span>${visibleCampaigns().length} of ${campaigns.length} campaigns</span><span>Demo actions do not publish real ads</span></div></div>`}
const accountKeys=()=>Object.keys(profiles);
function accountView(){return head('Ad accounts','Manage account connections and access.','<button class="primary" data-action="connect">Connect account</button>')+`<div class="cards">${accountKeys().map((key,i)=>{let [p,b]=key.split(' / ');return `<article class="account-card"><div class="account-head">${platform(p)}<div><h3>${b}</h3><small>${p} Ads · DEMO-${2001+i}</small></div></div><dl class="account-details"><div><dt>Connection</dt><dd>${badge('Sample')}</dd></div><div><dt>Campaigns</dt><dd>${campaigns.filter(c=>c.platform===p&&c.brand===b).length}</dd></div><div><dt>Currency</dt><dd>INR</dd></div><div><dt>Network profile</dt><dd>${esc(profiles[key].split(' · ')[0])}</dd></div></dl><button data-action="account" data-id="${i}">Manage account </button></article>`}).join('')}</div><p class="note">All accounts are illustrative. Production connections require official authorization and the appropriate platform permissions. No login credentials are requested in this demo.</p>`}
function assetView(){return head('Creative library','Keep approved creative close to the campaigns that use it.','<button data-action="asset-guide">Creative specifications</button>')+`<div class="cards">${assets.map((a,i)=>`<article class="asset-card"><div class="asset-art ${a.style}"><span class="art-tag">${a.tag}</span><b>${a.headline}</b><span class="art-bottom">${a.line}</span></div><div class="asset-body"><h3>${a.title}</h3><div class="asset-meta"><span>${a.brand}</span><span>Concept ${i+1}</span></div><button data-action="use-asset" data-id="${i}">Use in campaign </button></div></article>`).join('')}</div><p class="note">Typography-based sample concepts, not uploaded production files. Asset upload, format validation and platform delivery are represented by the proposed production workflow.</p>`}
function networkView(){return head('Network profiles','Assign a dedicated outbound route to each account.','<button data-action="network-info">How routing works</button>')+`<div class="network-banner"><div><h2>Account network assignments</h2><p>These profiles represent server-side API routes. They do not change your browser’s IP or start a device VPN.</p></div><span class="badge">SIMULATION ONLY</span></div><div class="panel"><div class="panel-head"><div><h2>Account assignments</h2><p>Six accounts · Four illustrative network profiles</p></div></div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Assigned route</th><th>Mode</th><th>Status</th><th></th></tr></thead><tbody>${accountKeys().map((k,i)=>`<tr><td class="campaign-name">${k.split(' / ')[1]}<small>${k.split(' / ')[0]} Ads</small></td><td>${esc(profiles[k])}</td><td>Dedicated outbound IP</td><td>${badge('Sample')}</td><td><button class="row-button" data-action="route" data-id="${i}">Configure</button></td></tr>`).join('')}</tbody></table></div></div><p class="note">Real VPN/proxy provisioning and platform compatibility are validated during the POC. Isolated access to actual Ads Manager websites requires a separately scoped remote-browser solution.</p>`}
function reportsView(){return head('Reports','Download performance, account and budget reports.')+stats()+`<div class="report-grid">${[['performance','Campaign performance','Spend, attributed revenue, conversions and ROAS by campaign.'],['accounts','Account directory','Sample account inventory, currency and assigned outbound network profile.'],['budgets','Budget & approval register','Daily budgets, objectives and the current approval state of each campaign.']].map(([k,t,s])=>`<article class="panel report-card"><div class="big-icon">▤</div><h3>${t}</h3><p>${s}</p><button data-action="export" data-type="${k}">↓ Download CSV</button></article>`).join('')}</div><div class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>Reading this report</h2><p>11–17 September 2026 · Sample INR accounts</p></div></div><div style="padding:0 24px 24px" class="sub">Revenue is illustrative and platform-attributed. Attribution windows and conversion definitions differ between platforms. Blended ROAS is revenue divided by spend; it is not a deduplicated cross-channel attribution measure.</div></div>`}
const views={overview,campaigns:campaignView,accounts:accountView,assets:assetView,network:networkView,reports:reportsView};
function render(){const prior=document.activeElement;const priorId=prior?.id;const priorFilter=prior?.dataset?.filter;const priorChart=prior?.dataset?.chart;let route=location.hash.slice(1)||'overview';if(!Object.hasOwn(routes,route))route='overview';currentRoute=route;$('#crumb').textContent=routes[route];document.title=routes[route]+' · Ad Workspace';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+route);if(a.hash==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#main').innerHTML=views[route]();$('.nav-count').textContent=campaigns.length;if(prior&&!prior.isConnected){let target=priorId?document.getElementById(priorId):null;if(!target&&priorFilter)target=[...document.querySelectorAll('[data-filter]')].find(b=>b.dataset.filter===priorFilter);if(!target&&priorChart)target=[...document.querySelectorAll('[data-chart]')].find(b=>b.dataset.chart===priorChart);(target||$('#main')).focus({preventScroll:true})}}
let focusBefore;function modal(title,sub,body){focusBefore=document.activeElement;$('#dialog').innerHTML=`<div class="modal-head"><div><div class="eyebrow">Demo workspace</div><h2 id="modal-title">${title}</h2><p class="sub" id="modal-description">${sub}</p></div><button class="close" aria-label="Close dialog" data-action="close">×</button></div><div class="modal-body">${body}</div>`;$('#dialog').setAttribute('aria-labelledby','modal-title');$('#dialog').setAttribute('aria-describedby','modal-description');$('#dialog').showModal();}
function close(){if($('#dialog').open)$('#dialog').close();if(focusBefore?.isConnected)focusBefore.focus();else $('#main').focus({preventScroll:true})}
function create(asset=0){if(campaigns.length>=100)return toast('Demo limit reached. Reset sample data to start again.');modal('Create a campaign','Build a sample draft. No advertising account will be contacted.',`<form id="create-form"><div class="form-grid"><label class="full">Campaign name<input name="name" maxlength="100" placeholder="e.g. September product launch" required></label><label>Ad account<select name="account">${accountKeys().map((k,i)=>`<option value="${i}" ${i===(asset===1?3:asset===2?2:0)?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label>Objective<select name="objective"><option>Sales</option><option>Traffic</option><option>Leads</option><option>Awareness</option></select></label><label>Daily budget (INR)<input name="budget" type="number" min="100" max="1000000" step="100" value="1500" required></label><label>Creative concept<select name="asset">${assets.map((a,i)=>`<option value="${i}" ${i===asset?'selected':''}>${a.title}</option>`).join('')}</select></label><div class="inline-note full">This demo uses a simplified objective list. Production choices will follow the selected platform’s supported campaign types.</div></div><div class="modal-actions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save draft</button></div></form>`)}
function detail(id){const c=campaigns.find(c=>c.id===id);if(!c)return;modal(esc(c.name),`${esc(c.brand)} · ${c.platform} Ads · ${esc(c.objective)}`,`<div class="detail-stats"><div><small>Spend</small><strong>${money(c.spend)}</strong></div><div><small>Conversions</small><strong>${c.conversions}</strong></div><div><small>ROAS</small><strong>${c.spend?(c.revenue/c.spend).toFixed(2)+'×':'—'}</strong></div></div><dl class="detail-list"><div><dt>Status</dt><dd>${badge(c.status)}</dd></div><div><dt>Creative</dt><dd>${assets[c.asset].title}</dd></div><div><dt>Network profile</dt><dd>${esc(profiles[c.platform+' / '+c.brand]||'Unassigned')}</dd></div></dl><button data-action="targeting" data-id="${c.id}" style="width:100%;margin-bottom:20px">Edit targeting & schedule </button><form id="budget-form" data-id="${c.id}"><label>Daily budget (INR)<div style="display:flex;gap:10px;margin-top:9px"><input name="budget" type="number" aria-label="Daily budget in INR" min="100" max="1000000" step="100" value="${c.budget}" required><button type="submit">Save budget</button></div></label></form><p class="note">Historical sample metrics remain unchanged when you edit a campaign. This is a workspace approval demonstration, not a platform review.</p><div class="modal-actions"><button data-action="close">Close</button><button class="primary" data-action="status" data-id="${c.id}">${c.status==='Draft'?'Submit for review':c.status==='In review'?'Approve & simulate publish':c.status==='Active'?'Pause campaign':'Resume campaign'}</button></div>`)}
function routeModal(i){const key=accountKeys()[i];if(!key)return;modal('Configure network profile',esc(key),`<form id="route-form" data-id="${i}"><label>Assigned outbound route<select name="profile" style="margin-top:10px">${[...new Set(Object.values(profiles)),'Mumbai · Dedicated 01','Mumbai · Dedicated 02','Singapore · Dedicated 03','London · Dedicated 04'].filter((v,i,a)=>a.indexOf(v)===i).map(p=>`<option ${p===profiles[key]?'selected':''}>${esc(p)}</option>`).join('')}</select></label><div class="inline-note" style="margin-top:18px">No VPN is started and no IP is changed. Production routing runs on the backend and requires validated infrastructure.</div><div id="check-result" role="status" class="check-result"></div><div class="modal-actions"><button type="button" data-action="check-route">Run sample check</button><button class="primary" type="submit">Save assignment</button></div></form>`)}
function exportCsv(type){let data;if(type==='accounts')data=[['Account','Platform','Currency','Network profile','Data type'],...accountKeys().map(k=>[k.split(' / ')[1],k.split(' / ')[0],'INR',profiles[k],'Sample'])];else if(type==='budgets')data=[['Campaign','Account','Platform','Objective','Daily budget INR','Status'],...campaigns.map(c=>[c.name,c.brand,c.platform,c.objective,c.budget,c.status])];else data=[['Campaign','Account','Platform','Status','Spend INR','Attributed revenue INR','Conversions','ROAS','Period','Data type'],...(type==='filtered'?visibleCampaigns():campaigns).map(c=>[c.name,c.brand,c.platform,c.status,c.spend,c.revenue,c.conversions,c.spend?(c.revenue/c.spend).toFixed(2):'','11-17 September 2026','Sample'])];const csv='\ufeff'+data.map(row=>row.map(v=>{let s=String(v);if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`SRS_Ad_Workspace_${type}_sample.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample report downloaded.')}
function go(route){if(location.hash==='#'+route)render();else location.hash=route;document.body.classList.remove('menu-open');$('.mobile-toggle').setAttribute('aria-expanded','false')}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b){const id=Number(b.dataset.id);switch(b.dataset.action){case'close':close();break;case'create':create();break;case'use-asset':create(id);break;case'detail':detail(id);break;case'clear':filter='All';platformFilter='All';query='';render();break;case'go':go(b.dataset.route);break;case'reviews':filter='In review';query='';platformFilter='All';go('campaigns');break;case'export':exportCsv(b.dataset.type);break;case'status':{const c=campaigns.find(c=>c.id===id);if(!c)break;const next={Draft:'In review','In review':'Active',Active:'Paused',Paused:'Active'}[c.status];c.status=next;save();close();render();toast(next==='Active'?'Campaign active in demo. No real ad was published.':`Campaign moved to ${next.toLowerCase()}.`);break}case'targeting':close();targetingModal(id);break;case'route':routeModal(id);break;case'check-route':$('#check-result').textContent='Sample check passed: route assigned, credentials represented, connection simulated.';break;case'account':{let k=accountKeys()[id];modal('Account settings',esc(k),`<dl class="detail-list"><div><dt>Authorization</dt><dd>Sample connection</dd></div><div><dt>Access</dt><dd>Workspace administrator</dd></div><div><dt>Network profile</dt><dd>${esc(profiles[k])}</dd></div></dl><div class="inline-note">This is an illustrative account. No tokens, passwords or live account data are stored.</div><div class="modal-actions"><button class="primary" data-action="account-route" data-id="${id}">Configure network</button></div>`);break}case'account-route':close();routeModal(id);break;case'connect':modal('Connect an advertising account','Preview the production connection process.',`<div class="connect-platforms">${Object.entries(symbols).map(([p])=>`<button data-action="connect-info" data-platform="${p}">${platform(p)}${p} Ads</button>`).join('')}</div><p class="note">A real connection redirects to the platform’s official authorization flow. This demo does not request credentials.</p>`);break;case'connect-info':{const p=b.dataset.platform;close();modal(`Connect ${p} Ads`,'Demonstration only',`<ol class="sub" style="padding-left:20px;line-height:2.2"><li>Authorize using the platform’s official sign-in.</li><li>Select the accounts you are permitted to manage.</li><li>Confirm permissions and assign your team.</li><li>Validate access and start the first sync.</li></ol><div class="inline-note">${p} is not connected. Production support depends on approved API access and the signed feature matrix.</div><div class="modal-actions"><button class="primary" data-action="close">Understood</button></div>`);break}case'network-info':modal('Two different network requirements','Choose the production approach during technical discovery.',`<h3>Account-specific API routing</h3><p class="sub">Backend requests use an approved dedicated route. This does not change the IP of the user’s browser.</p><h3>Isolated Ads Manager browsing</h3><p class="sub">Opening actual platform websites in independent sessions requires additional remote-browser infrastructure. A standard PWA alone cannot control a device VPN.</p><div class="modal-actions"><button class="primary" data-action="close">Understood</button></div>`);break;case'asset-guide':modal('Creative specifications','Platform-specific validation is part of the proposed production system.',`<p class="sub">These concepts demonstrate how assets can be organized and selected for campaigns. The production library will validate file type, dimensions, duration and size against the selected placement and platform.</p><div class="inline-note" style="margin-top:20px">Final production files and platform approval are not represented by these typography-only samples.</div><div class="modal-actions"><button class="primary" data-action="close">Close</button></div>`);break;case'confirm-reset':campaigns=structuredClone(initial);Object.assign(profiles,{'Meta / Northstar Studio':'Mumbai · Dedicated 01','Google / Northstar Studio':'Mumbai · Dedicated 02','Meta / Form & Field':'Singapore · Dedicated 03','LinkedIn / Orbit Software':'London · Dedicated 04','TikTok / Form & Field':'Singapore · Dedicated 03','Google / Orbit Software':'Mumbai · Dedicated 02'});query='';filter='All';platformFilter='All';save();close();render();toast('Sample workspace restored.');break}}
if(e.target.matches('[data-filter]')){filter=e.target.dataset.filter;render()}
if(e.target.closest('nav a')){document.body.classList.remove('menu-open');$('.mobile-toggle').setAttribute('aria-expanded','false')}
});
document.addEventListener('submit',e=>{const f=e.target;if(!['create-form','budget-form','route-form','targeting-form'].includes(f.id))return;e.preventDefault();const fd=new FormData(f);if(f.id==='create-form'){let name=String(fd.get('name')).trim();if(!name){f.elements.name.setCustomValidity('Enter a campaign name.');f.elements.name.reportValidity();return}const key=accountKeys()[Number(fd.get('account'))];if(!key)return;const [p,b]=key.split(' / ');campaigns.unshift({id:Math.max(...campaigns.map(c=>c.id))+1,name,brand:b,platform:p,objective:fd.get('objective'),status:'Draft',budget:Number(fd.get('budget')),spend:0,revenue:0,conversions:0,asset:Number(fd.get('asset'))});save();close();filter='Draft';platformFilter='All';query='';go('campaigns');toast('Draft saved. Open Review to submit for approval.')}else if(f.id==='budget-form'){let c=campaigns.find(c=>c.id===Number(f.dataset.id));if(c){c.budget=Number(fd.get('budget'));save();render();toast('Daily budget saved in the demo.')}}else if(f.id==='targeting-form'){let c=campaigns.find(c=>c.id===Number(f.dataset.id));if(!c)return;const targeting={region:String(fd.get('region')),terms:String(fd.get('terms')).slice(0,1000),negatives:String(fd.get('negatives')||'').slice(0,1000),start:String(fd.get('start')),end:String(fd.get('end'))};if(targeting.end<targeting.start){f.elements.end.setCustomValidity('End date must be after the start date.');f.elements.end.reportValidity();return}c.targeting=targeting;save();close();render();toast('Sample targeting and schedule saved.')}else{profiles[accountKeys()[Number(f.dataset.id)]]=fd.get('profile');save();close();render();toast('Sample network assignment saved.')}});
document.addEventListener('input',e=>{if(['name','start','end'].includes(e.target.name))e.target.setCustomValidity('');if(['start','end'].includes(e.target.name))e.target.form?.elements.end?.setCustomValidity('');if(e.target.id==='search'){query=e.target.value;$('#campaign-results').innerHTML=rows(visibleCampaigns())+`<div class="panel-bottom">${visibleCampaigns().length} of ${campaigns.length} campaigns</div>`}});
document.addEventListener('change',e=>{if(e.target.id==='platform-filter'){platformFilter=e.target.value;render()}});
$('#reset').onclick=()=>modal('Reset sample workspace?','Your demo campaign edits and network assignments will be cleared.',`<p class="sub">This only restores sample data in this browser tab. No real advertising account is affected.</p><div class="modal-actions"><button data-action="close">Keep changes</button><button class="primary" data-action="confirm-reset">Reset sample data</button></div>`);
$('.mobile-toggle').onclick=()=>{let open=document.body.classList.toggle('menu-open');$('.mobile-toggle').setAttribute('aria-expanded',String(open))};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');$('.mobile-toggle').setAttribute('aria-expanded','false')}});
window.addEventListener('hashchange',()=>{close();render();$('#main').focus();window.scrollTo(0,0)});render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_sample_campaigns',title:'List sample campaigns',description:'Read the current demo campaigns; no live advertising data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>{if(!window.demoSession)throw new Error('Complete the demo login and network check first.');return ({campaigns:campaigns.map(({id,name,platform,status,budget})=>({id,name,platform,status,dailyBudgetINR:budget}))})}})).catch(()=>{})}catch(e){}}

function targetingModal(id){const c=campaigns.find(c=>c.id===id);if(!c)return;const t=c.targeting||{region:'India',terms:c.platform==='Google'?'everyday essentials\npremium essentials':'People interested in design, lifestyle and online shopping',negatives:'free\njobs',start:'2026-09-18',end:'2026-09-30'};modal('Targeting & schedule',esc(c.name),`<form id="targeting-form" data-id="${id}"><div class="form-grid"><label class="full">Location<input name="region" maxlength="100" value="${esc(t.region)}" required></label><label class="full">${c.platform==='Google'?'Search keywords (one per line)':'Audience brief'}<textarea name="terms" maxlength="1000" required>${esc(t.terms)}</textarea></label>${c.platform==='Google'?`<label class="full">Negative keywords (one per line)<textarea name="negatives" maxlength="1000">${esc(t.negatives)}</textarea></label>`:''}<label>Start date<input type="date" name="start" value="${esc(t.start)}" required></label><label>End date<input type="date" name="end" value="${esc(t.end)}" required></label><div class="inline-note full">Demo configuration only. No scheduled jobs or live targeting changes are submitted. Production options depend on the platform.</div></div><div class="modal-actions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save configuration</button></div></form>`)}

$('#dialog').addEventListener('cancel',e=>{e.preventDefault();close()});
